absorb.source:
class AbsorbStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit)
const damage = [30, 60, 120, 240][pokemon.stars - 1] ?? 240
target.handleSpecialDamage(damage, board, AttackType.SPECIAL, pokemon, crit)
const cells = board.getAdjacentCells(
pokemon.positionX,
pokemon.positionY,
true
)
cells.forEach((cell) => {
if (cell.value && cell.value.team === pokemon.team) {
cell.value.handleHeal(damage * 0.1, pokemon, 1, crit)
}
})
}
}

accelerock.source:
class AccelerockStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
const destination = board.getFarthestTargetCoordinateAvailablePlace(pokemon)
target = destination?.target ?? target
super.process(pokemon, board, target, crit)
if (destination) {
pokemon.moveTo(destination.x, destination.y, board, false)
pokemon.setTarget(destination.target)
}
const damageFactor = [1, 1.25, 2.5][pokemon.stars - 1] ?? 2.5
target.handleSpecialDamage(
pokemon.atk * damageFactor,
board,
AttackType.SPECIAL,
pokemon,
crit,
true
)
const nbEffects = max(Math.floor(pokemon.def / 2))(
Math.round(5 * (1 + pokemon.ap / 100) * (crit ? pokemon.critPower : 1))
)
pokemon.addDefense(-2 * nbEffects, pokemon, 0, false)
pokemon.addSpeed(nbEffects * 5, pokemon, 0, false)
}
}

acid-armor.source:
class AcidArmorStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit)
const defGain = [3, 6, 12, 25][pokemon.stars - 1] ?? 25
pokemon.addDefense(defGain, pokemon, 1, crit)
let count = 4
const acidHitEffect = new OnDamageReceivedEffect(
({ pokemon, attacker }) => {
if (
attacker &&
distanceC(
pokemon.positionX,
pokemon.positionY,
attacker.positionX,
attacker.positionY
) === 1
) {
attacker.addDefense(-1, pokemon, 0, false)
}
count--
if (count <= 0) {
pokemon.effectsSet.delete(acidHitEffect)
}
}
)
pokemon.effectsSet.add(acidHitEffect)
}
}

acid-spray.source:
class AcidSprayStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit, true)
let tg= target
const affectedTargetsIds = new Array()
const damage = [11, 22, 33, 66][pokemon.stars - 1] ?? 66
for (let i = 0; i < 5; i++) {
if (tg) {
pokemon.broadcastAbility({
targetX: tg.positionX,
targetY: tg.positionY
})
tg.addSpecialDefense(-5, pokemon, 0, false)
tg.handleSpecialDamage(damage, board, AttackType.SPECIAL, pokemon, crit)
affectedTargetsIds.push(tg.id)
const cells = board.getAdjacentCells(tg.positionX, tg.positionY)
tg = cells
.filter(
(v) =>
v.value &&
v.value.team !== pokemon.team &&
!affectedTargetsIds.includes(v.value.id)
)
.map((v) => v.value)[0]
} else {
break
}
}
}
}

acrobatics.source:
class AcrobaticsStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit)
const damage = [20, 40, 80, 160][pokemon.stars - 1] ?? 160
target.handleSpecialDamage(damage, board, AttackType.SPECIAL, pokemon, crit)
const travelDistance = 4 - pokemon.items.size
const candidateDestinationCells = board
.getCellsInRadius(pokemon.targetX, pokemon.targetY, pokemon.range, false)
.filter((cell) => cell.value === undefined)
.sort(
(a, b) =>
Math.abs(
travelDistance -
distanceM(a.x, a.y, pokemon.positionX, pokemon.positionY)
) -
Math.abs(
travelDistance -
distanceM(b.x, b.y, pokemon.positionX, pokemon.positionY)
)
)
if (candidateDestinationCells.length > 0) {
const destination = candidateDestinationCells[0]
pokemon.moveTo(destination.x, destination.y, board, false)
}
}
}

