} else {
cell.value.handleSpecialDamage(
damage,
board,
AttackType.SPECIAL,
pokemon,
crit
)
if (i === ticks.length - 1) {
cell.value.status.triggerCharm(
1000,
cell.value,
pokemon,
false
)
cell.value.broadcastAbility({
targetX: cell.value.positionX,
targetY: cell.value.positionY,
