[
PRECOMPUTED_POKEMONS_PER_RARITY.COMMON,
PRECOMPUTED_POKEMONS_PER_RARITY.UNCOMMON,
PRECOMPUTED_POKEMONS_PER_RARITY.RARE
][pokemon.stars - 1] ?? PRECOMPUTED_POKEMONS_PER_RARITY.RARE
).filter((pkm) => {
const data = getPokemonData(pkm)
