fling.source:
class FlingStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit)
if (pokemon.items.has(Item.BALL)) {
let receiver= null
let maxDistance = 0
const fieldAllies = board.cells.filter(
(p)=>
p != null &&
p.id !== pokemon.id &&
p.team === pokemon.team &&
p.items.size < 3 &&
p.items.has(Item.BALL) === false &&
p.types.has(Synergy.FIELD)
)
let furthestFieldAlly= null
for (const ally of fieldAllies) {
const distance = distanceM(
ally.positionX,
ally.positionY,
pokemon.positionX,
pokemon.positionY
)
if (distance > maxDistance) {
furthestFieldAlly = ally
maxDistance = distance
}
}
if (furthestFieldAlly) {
receiver = furthestFieldAlly
} else {
const enemies = board.cells.filter(
(p)=> p != null && p.team !== pokemon.team
)
let furthestEnemy= null
let maxDistance = 0
for (const enemy of enemies) {
const distance = distanceM(
enemy.positionX,
enemy.positionY,
pokemon.positionX,
pokemon.positionY
)
if (distance > maxDistance) {
furthestEnemy = enemy
maxDistance = distance
}
}
if (furthestEnemy) {
receiver = furthestEnemy
}
}
if (receiver) {
const damageFactor = [0.3, 0.3, 0.3, 1][pokemon.stars - 1] ?? 1
const damage = Math.round(damageFactor * pokemon.speed)
effectInLine(board, pokemon, receiver, (cell) => {
if (cell.value && cell.value.team !== pokemon.team) {
cell.value.handleSpecialDamage(
damage,
board,
AttackType.SPECIAL,
pokemon,
crit,
true
)
}
})
}
} else {
const corner = board.getTeleportationCell(
pokemon.positionX,
pokemon.positionY,
pokemon.team
)
if (corner) {
pokemon.moveTo(corner.x, corner.y, board, false)
pokemon.commands.push(
new DelayedCommand(() => {
pokemon.addItem(Item.BALL)
}, 100)
)
}
}
}
}

