class FusionBoltStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit)
const electricLevel = pokemon.player?.synergies.get(Synergy.ELECTRIC)
const damage =
([30, 40, 50, 100][pokemon.stars - 1] ?? 100) +
(electricLevel ?? 0) * ([10, 10, 10, 20][pokemon.stars - 1] ?? 20)
