const count = [3, 4, 5, 6][pokemon.stars - 1] ?? 6
const enemies = board.getClosestEnemies(
pokemon.positionX,
pokemon.positionY,
pokemon.team === Team.RED_TEAM ? Team.BLUE_TEAM : Team.RED_TEAM
