damage,
board,
AttackType.SPECIAL,
pokemon,
crit
)
board
.getAdjacentCells(tg.positionX, tg.positionY)
.forEach((cell) => {
if (cell.value && cell.value.team !== pokemon.team) {
const { takenDamage } = cell.value.handleSpecialDamage(
Math.round(damage * 0.2),
board,
AttackType.SPECIAL,
pokemon,
crit
)
