pokemon.positionX,
pokemon.positionY,
pokemon.team
)
if (corner) {
pokemon.moveTo(corner.x, corner.y, board, false)
}
pokemon.commands.push(
new DelayedCommand(
() => {
const damage = ([3, 3, 3, 6][pokemon.stars - 1] ?? 6) * pokemon.atk
