class HeatCrashStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit)
let damage = [40, 60, 80, 160][pokemon.stars - 1] ?? 160
const attackDifference = pokemon.atk - target.atk
damage += attackDifference * 2
target.handleSpecialDamage(damage, board, AttackType.SPECIAL, pokemon, crit)
pokemon.orientation = board.orientation(
pokemon.positionX,
pokemon.positionY,
target.positionX,
target.positionY,
pokemon
)
const knockbackCell = board.getKnockBackPlace(
target.positionX,
target.positionY,
pokemon.orientation
