damage * (1 + (0.5 * (pokemon.maxHP - target.maxHP)) / target.maxHP)
)
}
board
.getAdjacentCells(pokemon.positionX, pokemon.positionY, false)
.forEach((cell) => {
if (cell.value && pokemon.team != cell.value.team) {
cell.value.handleSpecialDamage(
