if (data.rarity === Rarity.COMMON) {
candidatesWeights[p] = commonWeight
} else if (data.rarity === Rarity.UNCOMMON) {
candidatesWeights[p] = uncommonWeight
} else if (data.rarity === Rarity.RARE) {
