high-horsepower.source:
class HighHorsepowerStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit, true)
const damage = [15, 30, 60, 120][pokemon.stars - 1] ?? 120
const orientation = board.orientation(
pokemon.positionX,
pokemon.positionY,
target.positionX,
target.positionY,
pokemon
)
const destination = board.getKnockBackPlace(
target.positionX,
target.positionY,
orientation
)
if (destination) {
pokemon.moveTo(destination.x, destination.y, board, false)
}
pokemon.commands.push(
new DelayedCommand(() => {
pokemon.broadcastAbility({
positionX: pokemon.positionX,
positionY: pokemon.positionY
})
const adjacentEnemies = board
.getAdjacentCells(pokemon.positionX, pokemon.positionY, false)
.filter((cell) => cell.value && cell.value.team !== pokemon.team)
if (adjacentEnemies.length === 1) {
adjacentEnemies[0]?.value?.handleSpecialDamage(
damage * 2,
board,
AttackType.SPECIAL,
pokemon,
crit
)
} else if (adjacentEnemies.length > 1) {
for (const cell of adjacentEnemies) {
cell.value?.handleSpecialDamage(
damage,
board,
AttackType.SPECIAL,
pokemon,
crit
)
}
}
}, 300)
)
}
}

