pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit, true)
pokemon.cooldown = 1000
pokemon.broadcastAbility({
skill: "HYPER_BEAM_CHARGE",
positionX: pokemon.positionX,
positionY: pokemon.positionY
})
pokemon.commands.push(
new DelayedCommand(() => {
const damage = [65, 130, 250, 500][pokemon.stars - 1] ?? 500
pokemon.broadcastAbility({
skill: Ability.HYPER_BEAM,
targetX: target.positionX,
targetY: target.positionY
})
effectInLine(board, pokemon, target, (cell) => {
if (cell.value != null && cell.value.team !== pokemon.team) {
cell.value.handleSpecialDamage(
damage,
board,
AttackType.SPECIAL,
pokemon,
crit
)
}
})
pokemon.status.triggerFatigue(5000, pokemon, pokemon)
}, 1000)
)
}
}

hyper-drill.source:
class HyperDrillStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit, true)
const damage = [10, 20, 40, 50, 100][pokemon.stars - 1] ?? 100
const boardPlayer = target.simulation.bluePlayer
let doubleDamage = false
if (boardPlayer) {
const index = target.positionY * BOARD_WIDTH + target.positionX
if (boardPlayer.groundHoles[index] === SynergyConfigs.GROUND.maxDepth) {
doubleDamage = true
} else {
boardPlayer.groundHoles[index] =
(boardPlayer.groundHoles[index] ?? 0) + 1
}
pokemon.broadcastAbility({
targetX: target.positionX,
targetY: target.positionY,
delay: boardPlayer.groundHoles[index] // delay will hold the ground hole depth info
})
}
if (target.status.protect) {
target.status.protect = false
target.status.protectCooldown = 0
}
target.handleSpecialDamage(
damage * (doubleDamage ? 2 : 1),
board,
AttackType.TRUE,
pokemon,
crit
)
}
}

