class HyperspaceFuryStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit, true)
const nbHits = Math.round(
([1, 2, 3, 4, 8][pokemon.stars - 1] ?? 8) *
(1 + pokemon.ap / 100) *
(crit ? pokemon.critPower : 1)
)
for (let i = 0; i < nbHits; i++) {
target.addDefense(-1, pokemon, 0, false)
target.addSpecialDefense(-1, pokemon, 0, false)
target.handleSpecialDamage(
15,
board,
AttackType.SPECIAL,
pokemon,
false,
false
)
}
pokemon.broadcastAbility({
targetX: target.positionX,
targetY: target.positionY,
orientation: nbHits // use orientation field for the number of hits
})
}
}

hypnosis.source:
class HypnosisStrategy extends AbilityStrategy {
requiresTarget = false
process(pokemon, board, target, crit) {
const farthestTarget =
pokemon.state.getFarthestTarget(pokemon, board) ?? target
super.process(pokemon, board, farthestTarget, crit)
if (farthestTarget) {
const flatDuration = [1000, 1750, 3000, 6000][pokemon.stars - 1] ?? 1000
const durationWithAP = flatDuration * (2 + pokemon.ap / 100)
const critScalingFactor = 0.5
const duration = Math.round(
durationWithAP *
(crit ? 1 + (pokemon.critPower - 1) * critScalingFactor : 1)
)
farthestTarget.status.triggerSleep(duration, farthestTarget)
}
}
}

ice-spinner.source:
class IceSpinnerStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit, true)
const damage = [15, 30, 60, 120][pokemon.stars - 1] ?? 120
const cells = board.getAdjacentCells(
pokemon.positionX,
pokemon.positionY,
true
)
let delay = 0
for (const cell of cells) {
pokemon.commands.push(
new DelayedCommand(() => {
pokemon.broadcastAbility({
targetX: cell.x,
targetY: cell.y
})
board.clearBoardEffect(cell.x, cell.y, pokemon.simulation)
if (cell.value && cell.value.team !== pokemon.team) {
const orientation = board.orientation(
pokemon.positionX,
pokemon.positionY,
cell.value.positionX,
cell.value.positionY,
pokemon
)
const knockbackCell = board.getKnockBackPlace(
cell.value.positionX,
cell.value.positionY,
orientation
)
cell.value.handleSpecialDamage(
damage,
board,
AttackType.SPECIAL,
pokemon,
crit
)
if (knockbackCell) {
cell.value.moveTo(knockbackCell.x, knockbackCell.y, board, true)
cell.value.cooldown = 500
}
}
}, delay)
)
delay += 100
}
}
}

