class PoisonStingStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit)
let maxStacks = StatusConfigs.POISONED.maxStacks
if (pokemon.effects.has(EffectEnum.VENOMOUS)) {
maxStacks += EffectConfigs.VENOMOUS.maxStacksBonus
}
if (pokemon.effects.has(EffectEnum.TOXIC)) {
maxStacks =
StatusConfigs.POISONED.maxStacks + EffectConfigs.TOXIC.maxStacksBonus
}
const nbStacksToApply = [2, 3, 4, 5][pokemon.stars - 1] ?? 5
const currentStacks = target.status.poisonStacks
const extraDamage =
currentStacks + nbStacksToApply > maxStacks
? (currentStacks + nbStacksToApply - maxStacks) *
([25, 50, 100, 150][pokemon.stars - 1] ?? 150)
: 0
for (let i = 0; i < nbStacksToApply; i++) {
target.status.triggerPoison(4000, target, pokemon)
}
if (extraDamage > 0) {
target.handleSpecialDamage(
extraDamage,
board,
AttackType.SPECIAL,
pokemon,
crit
)
}
}
}

