pokemon,
crit
)
const speedNerf = max(cell.value.speed)(
speedFactor *
(1 + pokemon.ap / 100) *
(crit ? pokemon.critPower : 1)
)
cell.value.addSpeed(-speedNerf, pokemon, 0, false)
cell.value.commands.push(
new DelayedCommand(() => {
