present.source:
class PresentStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit)
const chance = Math.pow(Math.random(), 1 - pokemon.luck / 100)
/* 80 damage: 40%
150 damage: 30%
300 damage: 20%
heal 50HP: 10%
*/
const dmg80 = [20, 40, 80, 160][pokemon.stars - 1] ?? 160
const dmg150 = [50, 100, 150, 300][pokemon.stars - 1] ?? 300
const dmg300 = [100, 200, 300, 600][pokemon.stars - 1] ?? 600
if (chance < 0.1) {
target.handleHeal(50, pokemon, 0, false)
} else if (chance < 0.5) {
target.handleSpecialDamage(
dmg80,
board,
AttackType.SPECIAL,
pokemon,
crit
)
} else if (chance < 0.8) {
target.handleSpecialDamage(
dmg150,
board,
AttackType.SPECIAL,
pokemon,
crit
)
} else {
target.handleSpecialDamage(
dmg300,
board,
AttackType.SPECIAL,
pokemon,
crit
)
}
}
}

prismatic-laser.source:
class PrismaticLaserStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit)
const flip = pokemon.team === Team.RED_TEAM
for (let dx = -1; dx <= 1; dx++) {
const x = target.positionX + dx
if (x < 0 || x >= board.columns) continue
for (
let y = flip ? 0 : board.rows - 1;
flip ? y < board.rows : y >= 0;
y += flip ? 1 : -1
) {
const entityOnCell = board.getEntityOnCell(x, y)
if (entityOnCell && entityOnCell.team !== pokemon.team) {
entityOnCell.handleSpecialDamage(
[30, 40, 50, 60, 120][pokemon.stars - 1] ?? 120,
board,
AttackType.SPECIAL,
pokemon,
crit
)
const newY = y + (flip ? -1 : 1)
if (
newY >= 0 &&
newY < board.rows &&
board.getEntityOnCell(x, newY) == null
) {
entityOnCell.moveTo(x, newY, board, true)
}
}
}
}
}
}

