const baseDamage = [20, 40, 60, 120][pokemon.stars - 1] ?? 120
const singleTargetDamage = [60, 100, 140, 280][pokemon.stars - 1] ?? 280
const enemies = board
.getCellsInFront(pokemon, target)
.filter((cell) => cell.value && cell.value.team !== pokemon.team)
.map((cell) => cell.value)
