}
})
if (
pokemon.player &&
!pokemon.isGhostOpponent &&
pokemon.player.life < 100 &&
pokemon.passive === Passive.CELEBI &&
(!pokemon.player.doubleUpPartnerId || pokemon.count.ult === 1)
) {
