pokemon.addStack()
if (pokemon.player.doubleUpPartnerId) {
const partner = pokemon.simulation.room.state.players.get(
pokemon.player.doubleUpPartnerId
)
if (partner) {
partner.life = max(100)(partner.life + 1)
}
}
}
}
}

