class UproarStrategy extends AbilityStrategy {
requiresTarget = false
process(pokemon, board, target, crit) {
super.process(pokemon, board, target, crit)
board
.getCellsInRange(
pokemon.positionX,
pokemon.positionY,
pokemon.range,
true
)
.forEach((cell) => {
if (
cell.value &&
pokemon.team === cell.value.team &&
!cell.value.effects.has(EffectEnum.IMMUNITY_SLEEP)
) {
cell.value.effects.add(EffectEnum.IMMUNITY_SLEEP)
cell.value.commands.push(
new DelayedCommand(() => {
cell.value?.effects.delete(EffectEnum.IMMUNITY_SLEEP)
}, 3000)
)
}
})
for (let i = 1; i <= 3; i++) {
pokemon.commands.push(
new DelayedCommand(() => {
const damage = [5, 10, 20, 40][pokemon.stars - 1] ?? 40
pokemon.broadcastAbility()
board
.getCellsInRange(
pokemon.positionX,
pokemon.positionY,
pokemon.range,
false
)
.forEach((cell) => {
if (cell.value && pokemon.team != cell.value.team) {
cell.value.handleSpecialDamage(
damage,
board,
AttackType.SPECIAL,
pokemon,
crit
)
}
})
}, i * 1000)
)
}
}
}

