Ability.HIDDEN_POWER_J,
Ability.HIDDEN_POWER_K,
Ability.HIDDEN_POWER_L,
Ability.HIDDEN_POWER_M,
Ability.HIDDEN_POWER_N,
Ability.HIDDEN_POWER_O,
Ability.HIDDEN_POWER_P,
Ability.HIDDEN_POWER_Q,
Ability.HIDDEN_POWER_QM,
Ability.HIDDEN_POWER_R,
Ability.HIDDEN_POWER_S,
Ability.HIDDEN_POWER_T,
Ability.HIDDEN_POWER_U,
Ability.HIDDEN_POWER_V,
Ability.HIDDEN_POWER_W,
Ability.HIDDEN_POWER_X,
Ability.HIDDEN_POWER_Y,
Ability.HIDDEN_POWER_Z,
Ability.KNOWLEDGE_THIEF,
Ability.MAGNET_PULL,
Ability.METRONOME,
Ability.MIMIC,
Ability.ORDER_UP,
Ability.REVELATION_DANCE,
Ability.SHADOW_FORCE,
Ability.SKETCH,
Ability.SKILL_SWAP,
Ability.SWARM,
Ability.TRANSE,
Ability.UNBOUND
]
class AssistStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
const skill = pickRandomIn(
board.cells
.filter(
(v) =>
v &&
v.team === pokemon.team &&
v.skill &&
!InimitableAbilities.includes(v.skill)
)
.map((v) => v?.skill)
)
if (skill) {
pokemon.broadcastAbility({ skill })
AbilityStrategies[skill].process(pokemon, board, target, crit)
} else super.process(pokemon, board, target, crit)
}
}
class EncoreStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit)
const abilitiesCast =
pokemon.team === Team.BLUE_TEAM
? pokemon.simulation.blueAbilitiesCast
: pokemon.simulation.redAbilitiesCast
const lastAbilityUsed = abilitiesCast?.findLast(
(ability) => InimitableAbilities.includes(ability) === false
)
if (lastAbilityUsed) {
AbilityStrategies[lastAbilityUsed].process(pokemon, board, target, crit)
}
}
}
class KnowledgeThiefStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
if (InimitableAbilities.includes(target.skill) === false) {
AbilityStrategies[target.skill].process(pokemon, board, target, crit)
} else super.process(pokemon, board, target, crit)
if (pokemon.player && !pokemon.isGhostOpponent) {
const xpGain = [1, 1, 1, 2, 3][pokemon.stars - 1] ?? 3
const xpActuallyGained = pokemon.player.addExperience(xpGain)
pokemon.addStack(xpActuallyGained)
}
}
}
class MetronomeStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
const threshold = Math.pow(Math.random(), 1 + pokemon.luck / 100)
let rarity = Rarity.COMMON
if (threshold < 1 / 8) {
rarity = Rarity.ULTRA
} else if (threshold < 2 / 8) {
rarity = Rarity.LEGENDARY
} else if (threshold < 3 / 8) {
rarity = Rarity.EPIC
} else if (threshold < 4 / 8) {
rarity = Rarity.UNIQUE
} else if (threshold < 5 / 8) {
rarity = Rarity.RARE
} else if (threshold < 6 / 8) {
rarity = Rarity.SPECIAL
} else if (threshold < 7 / 8) {
rarity = Rarity.UNCOMMON
} else {
rarity = Rarity.COMMON
}
const pokemonOptions = [...PRECOMPUTED_POKEMONS_PER_RARITY[rarity]]
if (rarity === Rarity.SPECIAL) {
pokemonOptions.push(...PRECOMPUTED_POKEMONS_PER_RARITY[Rarity.HATCH])
}
const skillOptions = [
...new Set(pokemonOptions.map((p) => getPokemonData(p).skill))
]
const skill = pickRandomIn(
skillOptions.filter((s) => InimitableAbilities.includes(s) === false)
)
pokemon.broadcastAbility({ skill })
AbilityStrategies[skill].process(pokemon, board, target, crit)
pokemon.simulation.broadcastToSpectators(Transfer.DISPLAY_TEXT, {
id: pokemon.simulation.id,
text: `ability.${skill}`,
x: pokemon.positionX,
y: pokemon.positionY
})
}
}
class MimicStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
if (InimitableAbilities.includes(target.skill) === false) {
AbilityStrategies[target.skill].process(pokemon, board, target, crit)
} else super.process(pokemon, board, target, crit)
}
}
class SkillSwapStrategy extends AbilityStrategy {
process(
pokemon,
board,
target,
crit) {
super.process(pokemon, board, target, crit)
if (InimitableAbilities.includes(target.skill) === false) {
pokemon.skill = target.skill
pokemon.maxPP = target.refToBoardPokemon
? target.refToBoardPokemon.maxPP
: target.maxPP
if (
pokemon.refToBoardPokemon &&
!(
pokemon.refToBoardPokemon.skill === Ability.SKETCH &&
pokemon.refToBoardPokemon.tm === Ability.DEFAULT
)
) {
pokemon.refToBoardPokemon.skill = target.skill
pokemon.refToBoardPokemon.maxPP = target.maxPP
}
AbilityStrategies[target.skill].process(pokemon, board, target, crit)
}
}
}
